// Code generated by tgo. DO NOT EDIT.

package tgolint

import "encoding/json"
import jsonv2 "encoding/json/v2"
import "encoding/json/jsontext"
import "fmt"

import (
	"bytes"
	"go/token"
	"go/types"
	"path/filepath"
	"strconv"

	"tgo/pkg/format"
	"tgo/pkg/syntax"

	"golang.org/x/tools/go/analysis"
)

type verifiedSource struct {
	generated *syntax.File
	file      *syntax.File
	tokenFile *token.File
	data      []byte
}

// verifySourceModels checks generated declarations against their canonical source.
func (c *checker) verifySourceModels(generated *syntax.File) *verifiedSource {
	generatedPath := c.pass.Fset.Position(generated.Package).Filename
	generatedData, readErr := c.pass.ReadFile(generatedPath)
	sourceName := c.generatedSource[generated]
	if readErr != nil || sourceName == "" {
		c.failVerification(generated.Package, "generated tgo source mapping is invalid")
		return nil
	}
	sourcePath := filepath.Join(filepath.Dir(generatedPath), sourceName)
	data, err := readTGoSource(c.pass, sourcePath)
	if err != nil {
		c.failVerification(
			generated.Package,
			"cannot read tgo source %s: %v",
			sourceName,
			err,
		)
		return nil
	}
	if !bytes.Equal(generatedData, c.outputs[sourceName]) {
		c.failVerification(generated.Package, "generated tgo output integrity check failed")
		return nil
	}
	sourceFiles := token.NewFileSet()
	file, err := syntax.ParseFile(
		sourceFiles,
		sourcePath,
		data,
		syntax.ParseComments|syntax.AllErrors,
	)
	if err != nil {
		c.failVerification(
			generated.Package,
			"cannot parse tgo source %s: %v",
			sourceName,
			err,
		)
		return nil
	}
	sourceNames := make(map[string]bool)
	sourceToken := sourceFiles.File(file.Package)
	for _, declaration := range file.Declarations {
		if source := sourceDeclaration(
			declaration,
			c.packagePath(),
			file,
			sourceToken,
			data,
		); source != nil {
			sourceNames[sourceModelName(source)] = true
		}
		c.checkSourceDeclaration(
			generated,
			sourceName,
			file,
			declaration,
			sourceToken,
			data,
		)
	}
	c.reportExtraGeneratedModels(generated, sourceName, sourceNames)
	if c.invalid {
		return nil
	}
	return &verifiedSource{
		generated: generated,
		file:      file,
		tokenFile: sourceToken,
		data:      data,
	}
}

// exportSourceModels publishes facts only after every generated file verifies.
func (c *checker) exportSourceModels(source *verifiedSource) {
	for _, declaration := range source.file.Declarations {
		c.exportSourceDeclaration(
			source.generated,
			source.file,
			declaration,
			source.tokenFile,
			source.data,
		)
	}
}

func (c *checker) hasModelAPIs(object *types.TypeName) bool {
	return method(object.Type(), "Tag") != nil ||
		method(object.Type(), "check") != nil
}

// reportExtraGeneratedModels rejects model APIs with no matching TGo declaration.
func (c *checker) reportExtraGeneratedModels(
	file *syntax.File,
	sourceName string,
	sourceNames map[string]bool,
) {
	for _, declarationValue := range file.Declarations {
		general := syntax.GeneralDeclarationOf(declarationValue)
		if general == nil {
			continue
		}
		for _, item := range general.Specs {
			specification := syntax.TypeSpecificationOf(item)
			if specification == nil || sourceNames[specification.Name.Name] {
				continue
			}
			object, objectOK := c.facts.DefinitionName(specification.Name).(*types.TypeName)
			if !objectOK {
				continue
			}
			if c.hasModelAPIs(object) {
				c.failVerification(
					specification.Start,
					"generated tgo output for %s does not match %s",
					specification.Name.Name,
					sourceName,
				)
			}
		}
	}
}

// checkSourceDeclaration compares one TGo model with its generated Go API.
func (c *checker) checkSourceDeclaration(
	generated *syntax.File,
	sourceName string,
	file *syntax.File,
	declaration *syntax.Declaration,
	sourceFile *token.File,
	data []byte,
) {
	source := sourceDeclaration(
		declaration,
		c.packagePath(),
		file,
		sourceFile,
		data,
	)
	if source == nil {
		return
	}
	name := sourceModelName(source)
	specification := generatedTypeSpec(generated, name)
	if specification == nil {
		c.failVerification(
			generated.Package,
			"generated tgo output for %s does not match %s",
			name,
			sourceName,
		)
		return
	}
	object, objectOK := c.facts.DefinitionName(specification.Name).(*types.TypeName)
	if !objectOK || !sourceShapeMatches(
		generated,
		specification.Type,
		object.Type(),
		source,
	) {
		c.failVerification(
			specification.Start,
			"generated tgo output for %s does not match %s",
			name,
			sourceName,
		)
		return
	}
}

// exportSourceDeclaration records one verified model and its constructors.
func (c *checker) exportSourceDeclaration(
	generated *syntax.File,
	file *syntax.File,
	declaration *syntax.Declaration,
	sourceFile *token.File,
	data []byte,
) {
	source := sourceDeclaration(
		declaration,
		c.packagePath(),
		file,
		sourceFile,
		data,
	)
	if source == nil {
		return
	}
	name := sourceModelName(source)
	specification := generatedTypeSpec(generated, name)
	if specification == nil {
		return
	}
	object, ok := c.facts.DefinitionName(specification.Name).(*types.TypeName)
	if !ok {
		return
	}
	fact := sourceModelFact(source)
	if fact != nil {
		key := objectKey{pkg: object.Pkg(), name: object.Name()}
		c.models[key] = fact
		c.pass.ExportObjectFact(object, encodeModelFact(fact))
		c.exportValidationFacts(object, fact)
	}
}

func (c *checker) packagePath() string {
	if c.pass.Pkg == nil {
		return ""
	}
	return c.pass.Pkg.Path()
}

func tgosourceModelExternalJSONTo[T interface{}](out *jsontext.Encoder, name string, payload T) error {
	if err := out.WriteToken(jsontext.BeginObject); err != nil {
		return err
	}
	if err := out.WriteToken(jsontext.String(name)); err != nil {
		return err
	}
	if err := jsonv2.MarshalEncode(out, payload); err != nil {
		return err
	}
	return out.WriteToken(jsontext.EndObject)
}

// sourceModel requires a variant constructor. Its zero value is invalid.
// Shared data keeps Go aliases. Callers must keep model values valid.
type sourceModelTag uint8

const (
	sourceModelTagEnum sourceModelTag = iota + 1
	sourceModelTagStruct
)

type sourceModel struct {
	tgoTag     sourceModelTag
	tgoStruct  sourceModelStruct
	tgoPayload interface{}
}

// Tag returns the active tag.
func (v sourceModel) Tag() sourceModelTag { return v.tgoTag }

// UnknownTag describes an invalid tag.
func (v sourceModel) UnknownTag() string {
	return fmt.Sprintf("sourceModel: unknown tag %d — tgolint proves every tag has a case, so this is unreachable", v.tgoTag)
}

// sourceModelEnum is the Enum payload.
type sourceModelEnum struct {
	Name     string
	Fact     *model
	Variants []sourceVariant
}
type TgosourceModelEnumInput struct {
	FieldName     string
	FieldFact     *model
	FieldVariants []sourceVariant
}

// NewsourceModelEnum constructs sourceModel. Model fields must be valid.
// Shared fields keep their aliases and caller duties.
func NewsourceModelEnum(Name string, Fact *model, Variants []sourceVariant) sourceModel {
	tgoValue := sourceModelEnum{Name, Fact, Variants}
	return sourceModel{tgoTag: sourceModelTagEnum, tgoPayload: tgoValue}
}

// EnumPayload requires Enum. No tag check.
func (v sourceModel) EnumPayload() sourceModelEnum { return v.tgoPayload.(sourceModelEnum) }

// sourceModelStruct is the Struct payload.
type sourceModelStruct struct {
	Name   string
	Fact   *model
	Fields []sourceField
}
type TgosourceModelStructInput struct {
	FieldName   string
	FieldFact   *model
	FieldFields []sourceField
}

// NewsourceModelStruct constructs sourceModel. Model fields must be valid.
// Shared fields keep their aliases and caller duties.
func NewsourceModelStruct(Name string, Fact *model, Fields []sourceField) sourceModel {
	tgoValue := sourceModelStruct{Name, Fact, Fields}
	return sourceModel{tgoTag: sourceModelTagStruct, tgoStruct: tgoValue}
}

// StructPayload requires Struct. No tag check.
func (v sourceModel) StructPayload() sourceModelStruct { return v.tgoStruct }

func (v sourceModel) MarshalJSON() ([]byte, error) {
	switch v.tgoTag {
	case sourceModelTagEnum:
		payload := v.EnumPayload()
		return json.Marshal(struct {
			Payload sourceModelEnum `json:"Enum"`
		}{Payload: payload})
	case sourceModelTagStruct:
		payload := v.StructPayload()
		return json.Marshal(struct {
			Payload sourceModelStruct `json:"Struct"`
		}{Payload: payload})
	default:
		return nil, fmt.Errorf("invalid sourceModel JSON tag")
	}
}

func (v sourceModel) MarshalJSONTo(out *jsontext.Encoder) error {
	switch v.tgoTag {
	case sourceModelTagEnum:
		payload := v.EnumPayload()
		return tgosourceModelExternalJSONTo(out, "Enum", payload)
	case sourceModelTagStruct:
		payload := v.StructPayload()
		return tgosourceModelExternalJSONTo(out, "Struct", payload)
	default:
		return fmt.Errorf("invalid sourceModel JSON tag")
	}
}

func (v *sourceModel) UnmarshalJSON(data []byte) error {
	var variant string
	var payloadData []byte
	var object map[string]json.RawMessage
	if err := json.Unmarshal(data, &object); err != nil {
		return err
	}
	if len(object) != 1 {
		return fmt.Errorf("expected one sourceModel JSON variant")
	}
	for key, value := range object {
		variant = key
		payloadData = value
	}
	switch variant {
	case "Enum":
		var payload sourceModelEnum
		if err := json.Unmarshal(payloadData, &payload); err != nil {
			return err
		}
		*v = NewsourceModelEnum(payload.Name, payload.Fact, payload.Variants)
		return nil
	case "Struct":
		var payload sourceModelStruct
		if err := json.Unmarshal(payloadData, &payload); err != nil {
			return err
		}
		*v = NewsourceModelStruct(payload.Name, payload.Fact, payload.Fields)
		return nil
	default:
		return fmt.Errorf("unknown sourceModel JSON variant %q", variant)
	}
}

func (v *sourceModel) UnmarshalJSONFrom(in *jsontext.Decoder) error {
	token, err := in.ReadToken()
	if err != nil {
		return err
	}
	if token.Kind() != '{' {
		return fmt.Errorf("expected one sourceModel JSON variant")
	}
	var payloadData jsontext.Value
	var unknown string
	selected := 0
	haveName := false
	multiple := false
	for in.PeekKind() != '}' {
		nameToken, err := in.ReadToken()
		if err != nil {
			return err
		}
		wireName := nameToken.String()
		current := 0
		switch wireName {
		case "Enum":
			current = 1
		case "Struct":
			current = 2
		}
		same := haveName && current == selected
		if same && current == 0 {
			same = wireName == unknown
		}
		if !haveName {
			haveName = true
			selected = current
			if current == 0 {
				unknown = string(append([]byte(nil), wireName...))
			}
		} else if !same {
			multiple = true
		}
		if !multiple && current > 0 && current == selected {
			raw, err := in.ReadValue()
			if err != nil {
				return err
			}
			payloadData = append(payloadData[:0], raw...)
		} else if err := in.SkipValue(); err != nil {
			return err
		}
	}
	if _, err := in.ReadToken(); err != nil {
		return err
	}
	if !haveName || multiple {
		return fmt.Errorf("expected one sourceModel JSON variant")
	}
	if selected == 0 {
		return fmt.Errorf("unknown sourceModel JSON variant %q", unknown)
	}
	switch selected {
	case 1:
		var payload sourceModelEnum
		if err := jsonv2.Unmarshal(payloadData, &payload, in.Options()); err != nil {
			return err
		}
		*v = NewsourceModelEnum(payload.Name, payload.Fact, payload.Variants)
		return nil
	case 2:
		var payload sourceModelStruct
		if err := jsonv2.Unmarshal(payloadData, &payload, in.Options()); err != nil {
			return err
		}
		*v = NewsourceModelStruct(payload.Name, payload.Fact, payload.Fields)
		return nil
	default:
		return fmt.Errorf("invalid sourceModel JSON tag")
	}
}

// sourceDeclaration converts one syntax declaration to verified model metadata.
func sourceDeclaration(
	declaration *syntax.Declaration,
	packagePath string,
	file *syntax.File,
	sourceFile *token.File,
	data []byte,
) *sourceModel {
	if file == nil {
		return nil
	}
	if sourceFile == nil {
		return nil
	}
	if node, ok := syntax.EnumDeclarationOf(declaration); ok {
		if node == nil {
			return nil
		}
		variants := make([]string, 0, len(node.Variants))
		sourceVariants := make([]sourceVariant, 0, len(node.Variants))
		for _, variant := range node.Variants {
			if variant == nil {
				continue
			}
			variants = append(variants, variant.Name.Name)
			fields := []sourceField(nil)
			for _, field := range variant.Fields {
				if field != nil {
					fields = append(fields, sourceFields(file, sourceFile, data, field)...)
				}
			}
			sourceVariants = append(
				sourceVariants,
				sourceVariant{
					name:   variant.Name.Name,
					fields: fields,
				},
			)
		}
		result := func(input TgosourceModelEnumInput) sourceModel {
			return NewsourceModelEnum(input.FieldName, input.FieldFact, input.FieldVariants)
		}(TgosourceModelEnumInput{FieldName: node.Name.Name, FieldFact: enumModel(packagePath, node.Name.Name, variants), FieldVariants: sourceVariants})

		return &result
	}
	if node, ok := syntax.StructDeclarationOf(declaration); ok {
		if node == nil {
			return nil
		}
		fields := []sourceField(nil)
		for _, field := range node.Fields {
			if field != nil {
				fields = append(fields, sourceFields(file, sourceFile, data, field)...)
			}
		}
		var fact *model = nil
		if node.Checked != token.NoPos {
			fact = checkedModel(packagePath, node.Name.Name)
		}
		result := func(input TgosourceModelStructInput) sourceModel {
			return NewsourceModelStruct(input.FieldName, input.FieldFact, input.FieldFields)
		}(TgosourceModelStructInput{FieldName: node.Name.Name, FieldFact: fact, FieldFields: fields})

		return &result
	}
	return nil
}

func sourceModelName(value *sourceModel) string {
	if value == nil {
		return ""
	}
	switch item := *value; item.Tag() {
	case sourceModelTagEnum:
		return item.EnumPayload().Name
	case sourceModelTagStruct:
		return item.StructPayload().Name
	default:
		panic(item.UnknownTag()) // unreachable: tgolint requires a case per tag
	}
}

func sourceModelFact(value *sourceModel) *model {
	if value == nil {
		return nil
	}
	switch item := *value; item.Tag() {
	case sourceModelTagEnum:
		return item.EnumPayload().Fact
	case sourceModelTagStruct:
		return item.StructPayload().Fact
	default:
		panic(item.UnknownTag()) // unreachable: tgolint requires a case per tag
	}
}

func readTGoSource(pass *analysis.Pass, path string) ([]byte, error) {
	found := false
	for _, other := range pass.OtherFiles {
		if filepath.Clean(other) == filepath.Clean(path) {
			found = true
			break
		}
	}
	if !found {
		pass.OtherFiles = append(pass.OtherFiles, path)
	}
	data, err := pass.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("pass.ReadFile: %w", err)
	}
	return data, nil
}

func generatedTypeSpec(file *syntax.File, name string) *syntax.TypeSpecification {
	for _, declarationValue := range file.Declarations {
		general := syntax.GeneralDeclarationOf(declarationValue)
		if general == nil {
			continue
		}
		for _, item := range general.Specs {
			specification := syntax.TypeSpecificationOf(item)
			if specification != nil && specification.Name.Name == name {
				return specification
			}
		}
	}
	return nil
}

// sourceShapeMatches checks source fields and the public generated model API.
func sourceShapeMatches(
	generated *syntax.File,
	representation *syntax.Expression,
	typ types.Type,
	source *sourceModel,
) bool {
	if source == nil {
		return false
	}
	switch item := *source; item.Tag() {
	case sourceModelTagStruct:
		sourceStruct := item.StructPayload()
		structure := syntax.StructTypeExpressionOf(representation)
		if structure == nil {
			return false
		}
		if !sameFields(sourceStruct.Fields, structure.Fields.List, generated) {
			return false
		}
		return sourceStruct.Fact == nil || validCheckedStructAPI(typ)
	case sourceModelTagEnum:
		enum := item.EnumPayload()
		if !generatedEnumShape(typ, enum.Name, enum.Variants) {
			return false
		}
		for _, variant := range enum.Variants {
			payloadSpec := generatedTypeSpec(generated, enum.Name+variant.name)
			if payloadSpec == nil {
				return false
			}
			payload := syntax.StructTypeExpressionOf(payloadSpec.Type)
			if payload == nil || !sameFields(variant.fields, payload.Fields.List, generated) {
				return false
			}
		}
		return true
	default:
		panic(item.UnknownTag()) // unreachable: tgolint requires a case per tag
	}
}

func validCheckedStructAPI(typ types.Type) bool {
	signature := method(typ, "check")
	if signature == nil || signature.Recv() == nil || signature.Params().Len() != 0 ||
		signature.Results().Len() != 2 || signature.Variadic() {
		return false
	}
	errorObject := types.Universe.Lookup("error")
	return errorObject != nil && types.Identical(signature.Recv().Type(), typ) &&
		types.Identical(signature.Results().At(0).Type(), typ) &&
		types.Identical(signature.Results().At(1).Type(), errorObject.Type())
}

// generatedEnumShape checks enum operations without reading private storage.
func generatedEnumShape(
	typ types.Type,
	name string,
	variants []sourceVariant,
) bool {
	tag, ok := typeInPackage(typ, name+"Tag")
	if !ok || !validGeneratedTagAPI(typ, tag, name, variants) {
		return false
	}
	for _, variant := range variants {
		payloadName := name + variant.name
		payload, ok := typeInPackage(typ, payloadName)
		if !ok || !validEnumAPI(
			typ,
			payload,
			variant.name+"Payload",
			"New"+payloadName,
		) {
			return false
		}
		if len(variant.fields) > 0 {
			carrier, ok := typeInPackage(typ, "Tgo"+payloadName+"Input")
			if !ok || !validEnumCarrier(payload, carrier) {
				return false
			}
		}
	}
	return true
}

func validGeneratedTagAPI(
	typ types.Type,
	tagType types.Type,
	name string,
	variants []sourceVariant,
) bool {
	tag := method(typ, "Tag")
	unknown := method(typ, "UnknownTag")
	if tag == nil || tag.Params().Len() != 0 || tag.Results().Len() != 1 ||
		!types.Identical(tag.Results().At(0).Type(), tagType) ||
		unknown == nil || unknown.Params().Len() != 0 || unknown.Results().Len() != 1 ||
		!types.Identical(unknown.Results().At(0).Type(), types.Typ[types.String]) {
		return false
	}
	basic, ok := coreType(tagType).(*types.Basic)
	if !ok || basic.Info()&types.IsUnsigned == 0 {
		return false
	}
	named, ok := types.Unalias(typ).(*types.Named)
	if !ok || named.Obj().Pkg() == nil {
		return false
	}
	names := []string(nil)
	for _, variant := range variants {
		names = append(names, name+"Tag"+variant.name)
	}
	for index, constantName := range names {
		constant, ok := named.Obj().Pkg().Scope().Lookup(constantName).(*types.Const)
		if !ok || !types.Identical(constant.Type(), tagType) ||
			constant.Val().ExactString() != strconv.Itoa(index+1) {
			return false
		}
	}
	return true
}

func typeInPackage(typ types.Type, name string) (types.Type, bool) {
	named, ok := types.Unalias(typ).(*types.Named)
	if !ok || named.Obj().Pkg() == nil {
		return nil, false
	}
	object, ok := named.Obj().Pkg().Scope().Lookup(name).(*types.TypeName)
	if !ok {
		return nil, false
	}
	return object.Type(), true
}

// sameModelFact compares model identity and the ordered enum variants.
func sameModelFact(left *model, right *model) bool {
	if left == nil || right == nil || !sameModel(left, right) {
		return false
	}
	leftVariants := modelVariants(left)
	rightVariants := modelVariants(right)
	if len(leftVariants) != len(rightVariants) {
		return false
	}
	for index := range leftVariants {
		if leftVariants[index] != rightVariants[index] {
			return false
		}
	}
	return true
}

type sourceField struct {
	name           string
	typeExpression string
	tag            string
}

type sourceVariant struct {
	name   string
	fields []sourceField
}

func sourceFields(
	file *syntax.File,
	sourceFile *token.File,
	data []byte,
	declaration *syntax.TGoField,
) []sourceField {
	result := []sourceField(nil)
	typeText := sourceExpression(file, sourceFile, data, declaration.Field.Type)
	tagText := ""
	if declaration.Field.Tag != nil {
		tagText = sourceRange(
			sourceFile,
			data,
			declaration.Field.Tag.Start,
			declaration.Field.Tag.Stop,
		)
	}
	if len(declaration.Field.Names) == 0 {
		return []sourceField{{name: "", typeExpression: typeText, tag: tagText}}
	}
	for _, name := range declaration.Field.Names {
		result = append(
			result,
			sourceField{
				name:           name.Name,
				typeExpression: typeText,
				tag:            tagText,
			},
		)
	}
	return result
}

func sourceExpression(
	file *syntax.File,
	sourceFile *token.File,
	data []byte,
	expression *syntax.Expression,
) string {
	if expression == nil {
		return ""
	}
	start := syntax.ExpressionPosition(expression)
	end := syntax.ExpressionEnd(expression)
	result := []byte(
		sourceRange(
			sourceFile,
			data,
			syntax.ExpressionPosition(expression),
			syntax.ExpressionEnd(expression),
		),
	)
	for _, extension := range syntax.Extensions(file) {
		node, ok := syntax.NonNilPointerTypeOf(extension)
		if !ok || node.Percent < start || node.Percent >= end {
			continue
		}
		result[sourceFile.Offset(node.Percent)-sourceFile.Offset(start)] = '*'
	}
	return string(result)
}

func sourceRange(
	sourceFile *token.File,
	data []byte,
	start token.Pos,
	end token.Pos,
) string {
	return string(data[sourceFile.Offset(start):sourceFile.Offset(end)])
}

func sameFields(
	source []sourceField,
	generated []*syntax.Field,
	file *syntax.File,
) bool {
	if len(source) != len(generated) {
		return false
	}
	for index, field := range source {
		other := generated[index]
		if other == nil {
			return false
		}
		typeText := syntax.SourceText(
			file,
			syntax.Span{
				Start: syntax.ExpressionPosition(other.Type),
				Stop:  syntax.ExpressionEnd(other.Type),
			},
		)
		tagText := ""
		if other.Tag != nil {
			tagText = syntax.SourceText(file, other.Tag.Span)
		}
		if !sameTypeText(field.typeExpression, typeText) ||
			!sameTagText(field.tag, tagText) {
			return false
		}
		if field.name == "" && len(other.Names) == 0 {
			continue
		}
		if len(other.Names) != 1 || other.Names[0].Name != field.name {
			return false
		}
	}
	return true
}

func sameTypeText(left string, right string) bool {
	return sameFormattedText(
		left,
		right,
		func(text string) string {
			return "package p\ntype value " + text + "\n"
		},
	)
}

func sameTagText(left string, right string) bool {
	return sameFormattedText(
		left,
		right,
		func(text string) string {
			return "package p\ntype value struct { Field int " + text + " }\n"
		},
	)
}

func sameFormattedText(
	left string,
	right string,
	wrap func(string) string,
) bool {
	if left == right {
		return true
	}
	if left == "" || right == "" {
		return left == right
	}
	leftText, leftErr := format.Source("left.tgo", []byte(wrap(left)))
	rightText, rightErr := format.Source("right.tgo", []byte(wrap(right)))
	if leftErr != nil || rightErr != nil {
		return false
	}
	return string(leftText) == string(rightText)
}
